create table if not exists contas (id bigint generated by default as identity primary key, nome text not null, tipo text not null, categoria text, fornecedor_cliente text, valor numeric not null, emissao date, vencimento date not null, forma_pagamento text, status text default 'pendente', created_at timestamp default now()); create table if not exists contatos (id bigint generated by default as identity primary key, nome text not null, tipo text not null, created_at timestamp default now()); alter table contas disable row level security; alter table contatos disable row level security;